/**
 * Wordmark. O tratamento vem do site institucional: Poppins 600 em "Anank",
 * 400 em "Studios", caixa mista e tracking -0.01em. (Uma versão anterior
 * usava caixa alta com tracking +0.14em — não é a marca.)
 */
export function AnankMark({
  className,
  withSymbol = false,
}: {
  className?: string;
  withSymbol?: boolean;
}) {
  return (
    <span className={cn('inline-flex items-baseline gap-2', className)}>
      {withSymbol ? (
        <AnankSymbol className="size-[0.9em] self-center text-[color:var(--brand-accent)]" />
      ) : null}
      <span className="font-display tracking-[-0.01em]">
        <span className="font-semibold">Anank</span>
        <span className="font-normal"> Studios</span>
      </span>
    </span>
  );
}

/** Ícone de grid 2×2 — volta para o hub. */
export function GridIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      width="14"
      height="14"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      aria-hidden="true"
      className={className}
    >
      <rect x="1.5" y="1.5" width="5" height="5" />
      <rect x="9.5" y="1.5" width="5" height="5" />
      <rect x="1.5" y="9.5" width="5" height="5" />
      <rect x="9.5" y="9.5" width="5" height="5" />
    </svg>
  );
}
